### Describe the bug

I was testing out enum transpiling while looking into why it's adding `1` on the end of identifiers and noticed that it doesn't handle block scope correctly.

### Input code

```ts
{
    enum Asdf {
        test = 1
    }
    function test() {
        enum Asdf {
            test = 1
        }
        enum Asdf {
            other = 1
        } 
    }
}
enum Asdf {
    asdf = 1
}

export {}
```

### Config

```json
{
  "jsc": {
    "parser": {
      "syntax": "typescript",
      "tsx": false,
      "decorators": true
    },
    "target": "es2021",
    "loose": false,
    "minify": {
      "compress": false,
      "mangle": false
    }
  },
  "module": {
    "type": "es6"
  },
  "minify": false,
  "isModule": true
}
```


### Playground link

https://play.swc.rs/?version=1.2.111&code=H4sIAAAAAAAAA6vm5VIAgtS80lwFx%2BKUNIVqiAAIlKQWlyjYKhhCRGohVFppXnJJZn4eWFZDE1k9VkMwDUIyDK%2Bu%2FJKM1CI0bQpwtwARhs5EEBusASgLlK8oyC8qUaiuBQCjgBG25QAAAA%3D%3D&config=H4sIAAAAAAAAA0WOQQ7DIAwE%2F%2BJzDm0OPfCHPgIRJyIiGNmOVIT4ewGlzc3a3Rm5wC4OTIFkWZD7JTmq%2FYABzQnFsU8KE6i0aLVBcIIFHbFVYgGjfGJtteUNtUEo82N%2BNiAQCf6Rw0e%2F5q53dCRGkbuycQu%2FZW2ug5azB2V8MJwvqLfj4ry8r%2BH44QvfqNagygAAAA%3D%3D

### Expected behavior

Should output something close to the following, like TypeScript does:

```ts
{
    let Asdf;
    (function (Asdf) {
        Asdf[Asdf["test"] = 1] = "test";
    })(Asdf || (Asdf = {}));
    function test() {
        let Asdf;
        (function (Asdf) {
            Asdf[Asdf["test"] = 1] = "test";
        })(Asdf || (Asdf = {}));
        (function (Asdf) {
            Asdf[Asdf["other"] = 1] = "other";
        })(Asdf || (Asdf = {}));
    }
}
var Asdf;
(function (Asdf) {
    Asdf[Asdf["asdf"] = 1] = "asdf";
})(Asdf || (Asdf = {}));
export {};
```

### Actual Behaviour

```js
{
    var Asdf1;
    (function(Asdf) {
        Asdf[Asdf["test"] = 1] = "test";
    })(Asdf1 || (Asdf1 = {
    }));
    function test() {
        (function(Asdf) {
            Asdf[Asdf["test"] = 1] = "test";
        })(Asdf1 || (Asdf1 = {
        }));
        (function(Asdf) {
            Asdf[Asdf["other"] = 1] = "other";
        })(Asdf1 || (Asdf1 = {
        }));
    }
}(function(Asdf) {
    Asdf[Asdf["asdf"] = 1] = "asdf";
})(Asdf1 || (Asdf1 = {
}));
export { };
```

### Version

1.2.111

### Additional context

_No response_

comments:
Interestingly, it also merges with an enum inside a namespace:

```ts
enum Asdf {
    asdf = 1
}

namespace Test {
    enum Asdf {
       asdf = 2
    }   
}
```

Outputs:

```ts
var Asdf1;
(function(Asdf) {
    Asdf[Asdf["asdf"] = 1] = "asdf";
})(Asdf1 || (Asdf1 = {
}));
var Test;
(function(Test) {
    (function(Asdf) {
        Asdf[Asdf["asdf"] = 2] = "asdf";
    })(Asdf1 || (Asdf1 = {
    }));
})(Test || (Test = {
}));
```

Also, if you add an export keyword to that enum in the namespace it will have no effect.

Also occurs with namespaces:

```ts
namespace Test {
    export namespace Test {
        const t = 5;
    }
}

console.log(Test.Test.t)
```

Outputs:

```js
var Test;
(function(Test1) {
    (function(Test) {
        const t = 5;
    })(Test || (Test = {
    }));
})(Test || (Test = {
}));
console.log(Test.Test.t);
```

Expected:

```js
// ts compiler output
var Test;
(function (Test_1) {
    let Test;
    (function (Test) {
        const t = 5;
    })(Test = Test_1.Test || (Test_1.Test = {}));
})(Test || (Test = {}));
console.log(Test.Test.t);
```

This is because of the use of `create_uninit_var` in swc_ecma_transforms_typescript/src/strip.rs which does not take scope into account.
